css:
[data-workspace-area="conversation"] {
  position: relative;
  isolation: isolate;
  background: var(--texture-light, #e5e5e5) !important;
}
:root.dark [data-workspace-area="conversation"] {
  background: var(--texture-dark, #101010) !important;
}
[data-workspace-area="conversation"]::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: url("data:image/webp;base64,") center / 384px repeat;
  opacity: var(--texture-grain, .72);
  mix-blend-mode: luminosity;
}
:root:not(.dark) [data-workspace-area="conversation"]::before {
  /* Invert the charcoal wallpaper and amplify its narrow brightness range. */
  filter: grayscale(1) invert(1) brightness(.552) contrast(17);
  mix-blend-mode: multiply;
}

/* Some controls use the stock color scale directly. */
:root:not(.dark) {
  --color-red-50: #fafafa !important;
